SELECT analytics_order_facts.region, SUM(analytics_order_facts.contribution_margin) / CAST(NULLIF(SUM(analytics_order_facts.net_revenue), 0) AS DECIMAL) AS contribution_margin_pct FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 1 AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'consumer' AND analytics_order_facts.category = 'category_01' AND analytics_order_facts.payment_method = 'card' GROUP BY analytics_order_facts.region ORDER BY contribution_margin_pct DESC, analytics_order_facts.region ASC LIMIT 12
